// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(caller);
        try c.withdrawAll(caller) { ok = true; } catch { ok = false; }
        bool isOwner = caller == address(this);
        if (isOwner) {
            assertTrue(ok && address(c).balance == 0);
        } else {
            assertTrue(!ok && address(c).balance == balBefore);
        }
    }
}
